+/// provenance preserves diagnostics when a subclass redeclares either field.
+fn has_inherited_dataclass_field_order_violation<'db>(
+    db: &'db dyn Db,
+    class: StaticClassLiteral<'db>,
+    default_name: &Name,
+    default_field: &Field<'db>,
+    required_name: &Name,
+    required_field: &Field<'db>,
